	cond        *sync.Cond // signaled when a job is queued or the runner closes
	queue       []entry    // jobs not started yet, oldest first
	interrupted []entry    // jobs that Shutdown canceled and that returned an error
	running     map[uint64]*running
	seq         uint64
	closed      bool
	live        int           // workers that have not exited yet
	done        chan struct{} // closed once the runner is closed and no worker is live
}

// NewRunner returns a runner with workers workers and room for queueSize waiting jobs. A nil log discards.
func NewRunner(workers, queueSize int, log *slog.Logger) *Runner {
	if workers < 1 {
		workers = 1
	}
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	r := &Runner{
		workers:   workers,
		queueSize: queueSize,
		log:       log,
		running:   map[uint64]*running{},
		done:      make(chan struct{}),
	}
	r.cond = sync.NewCond(&r.mu)
	return r
}

// Start starts the workers. It does nothing once the runner is closed.
func (r *Runner) Start() {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return
	}
	r.live += r.workers
	for i := 0; i < r.workers; i++ {
		go r.work()
	}
}

func (r *Runner) work() {
	defer r.exit()
	for {
		r.mu.Lock()
		for len(r.queue) == 0 && !r.closed {
			r.cond.Wait()
		}
		if r.closed {
			r.mu.Unlock()
			return
		}
		e := r.queue[0]
		r.queue[0] = entry{}
		r.queue = r.queue[1:]
		ctx, cancel := context.WithCancel(context.Background())
		run := &running{cancel: cancel}
		r.running[e.seq] = run
		r.mu.Unlock()

		panicked, err := r.call(ctx, e.job)
		cancel()

		r.mu.Lock()
		delete(r.running, e.seq)
		if run.canceled && err != nil && !panicked {
			r.interrupted = append(r.interrupted, e)
		}
		r.mu.Unlock()
		if err != nil && !panicked {
			r.log.Error("job failed", "job", e.job.Name, "err", err)
		}
	}
}

// call runs j. A panic is logged and recovered, and reported as panicked.
func (r *Runner) call(ctx context.Context, j Job) (panicked bool, err error) {
	defer func() {
		if p := recover(); p != nil {
			r.log.Error("job panicked", "job", j.Name, "panic", p, "stack", string(debug.Stack()))
			panicked = true
		}
	}()
	return false, j.Run(ctx)
}

func (r *Runner) exit() {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.live--
	if r.closed && r.live == 0 {
		close(r.done)
	}
}

// Enqueue adds a job to the queue without waiting. It returns ErrQueueFull when the queue has no room
// and ErrStopped once the runner is shut down.
func (r *Runner) Enqueue(j Job) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.closed {
		return ErrStopped
	}
	if len(r.queue) >= r.queueSize {
		return ErrQueueFull
	}
	r.queue = append(r.queue, entry{seq: r.seq, job: j})
	r.seq++
	r.cond.Signal()
	return nil
}

// Shutdown stops the runner. From the moment it is called, Enqueue returns ErrStopped and jobs that have
// not started are not started. Shutdown waits for the running jobs to finish. If ctx ends first, it cancels
// their contexts, waits for them to return, and returns ctx.Err(). A second call returns nil at once.
func (r *Runner) Shutdown(ctx context.Context) error {
	r.mu.Lock()
	if r.closed {
		r.mu.Unlock()
		return nil
	}
	r.closed = true
	if r.live == 0 {
		close(r.done)
	}
	r.cond.Broadcast()
	r.mu.Unlock()

	select {
	case <-r.done:
		return nil
	default:
	}
	select {
	case <-r.done:
		return nil
	case <-ctx.Done():
	}
	r.cancelRunning()
	<-r.done
	return ctx.Err()
}

// cancelRunning cancels the context of every running job.
func (r *Runner) cancelRunning() {
	r.mu.Lock()
	defer r.mu.Unlock()
	for _, run := range r.running {
		run.canceled = true
		run.cancel()
	}
}

// Stop shuts the runner down like Shutdown, waiting at most 30 seconds for the running jobs.
func (r *Runner) Stop() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	_ = r.Shutdown(ctx)
}

// Pending returns the jobs that still need to run, in the order they were enqueued. Before Shutdown these are
// the queued jobs. After Shutdown they are the jobs that were never started, followed by the jobs that
// Shutdown canceled and that returned an error.
func (r *Runner) Pending() []Job {
	r.mu.Lock()
	defer r.mu.Unlock()
	interrupted := append([]entry(nil), r.interrupted...)
	sort.Slice(interrupted, func(i, j int) bool { return interrupted[i].seq < interrupted[j].seq })
	jobs := make([]Job, 0, len(r.queue)+len(interrupted))
	for _, e := range r.queue {
		jobs = append(jobs, e.job)
	}
	for _, e := range interrupted {
		jobs = append(jobs, e.job)
	}
	return jobs
}

