package jobs

import (
	"context"
	"errors"
	"runtime"
	"slices"
	"sync"
	"testing"
	"time"
)

func TestRunnerRunsJobs(t *testing.T) {
	r := NewRunner(3, 10, nil)
	r.Start()
	var mu sync.Mutex
	done := map[string]bool{}
	var wg sync.WaitGroup
	for _, name := range []string{"a", "b", "c", "d", "e"} {
		wg.Add(1)
		if err := r.Enqueue(Job{Name: name, Run: func(ctx context.Context) error {
			defer wg.Done()
			mu.Lock()
			done[name] = true
			mu.Unlock()
			return nil
		}}); err != nil {
			t.Fatal(err)
		}
	}
	finished := make(chan struct{})
	go func() { wg.Wait(); close(finished) }()
	select {
	case <-finished:
	case <-time.After(5 * time.Second):
		t.Fatal("jobs did not run")
	}
	if len(done) != 5 {
		t.Fatalf("done = %v", done)
	}
}

func TestEnqueueWhenFull(t *testing.T) {
	r := NewRunner(1, 1, nil) // not started: nothing takes jobs off the queue
	job := Job{Name: "x", Run: func(context.Context) error { return nil }}
	if err := r.Enqueue(job); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(job); !errors.Is(err, ErrQueueFull) {
		t.Fatalf("err = %v, want ErrQueueFull", err)
	}
}

// waitClosed waits until Shutdown has closed the runner.
func waitClosed(t *testing.T, r *Runner) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		r.mu.Lock()
		closed := r.closed
		r.mu.Unlock()
		if closed {
			return
		}
		if time.Now().After(deadline) {
			t.Fatal("runner did not close")
		}
		time.Sleep(time.Millisecond)
	}
}

// names returns the names of jobs, in order.
func names(jobs []Job) []string {
	out := []string{}
	for _, j := range jobs {
		out = append(out, j.Name)
	}
	return out
}

func noop(context.Context) error { return nil }

func TestPendingListsQueuedJobsInOrder(t *testing.T) {
	r := NewRunner(1, 10, nil) // not started
	for _, name := range []string{"a", "b", "c"} {
		if err := r.Enqueue(Job{Name: name, Run: noop}); err != nil {
			t.Fatal(err)
		}
	}
	if got := names(r.Pending()); !slices.Equal(got, []string{"a", "b", "c"}) {
		t.Fatalf("pending = %v, want [a b c]", got)
	}
}

func TestEnqueueAfterShutdown(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(Job{Name: "late", Run: noop}); !errors.Is(err, ErrStopped) {
		t.Fatalf("err = %v, want ErrStopped", err)
	}
	if got := names(r.Pending()); len(got) != 0 {
		t.Fatalf("pending = %v, want none", got)
	}
}

func TestShutdownDoesNotStartQueuedJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	release := make(chan struct{})
	ran := make(chan string, 10)
	if err := r.Enqueue(Job{Name: "first", Run: func(context.Context) error {
		close(started)
		<-release
		ran <- "first"
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started
	if err := r.Enqueue(Job{Name: "second", Run: func(context.Context) error {
		ran <- "second"
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	res := make(chan error, 1)
	go func() { res <- r.Shutdown(context.Background()) }()
	waitClosed(t, r)
	close(release)
	if err := <-res; err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	close(ran)
	var got []string
	for name := range ran {
		got = append(got, name)
	}
	if !slices.Equal(got, []string{"first"}) {
		t.Fatalf("ran = %v, want [first]", got)
	}
	if pending := names(r.Pending()); !slices.Equal(pending, []string{"second"}) {
		t.Fatalf("pending = %v, want [second]", pending)
	}
}

func TestShutdownWaitsForRunningJobs(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	release := make(chan struct{})
	finished := make(chan struct{})
	if err := r.Enqueue(Job{Name: "slow", Run: func(context.Context) error {
		close(started)
		<-release
		close(finished)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	<-started
	res := make(chan error, 1)
	go func() { res <- r.Shutdown(context.Background()) }()
	waitClosed(t, r)
	close(release)
	if err := <-res; err != nil {
		t.Fatalf("Shutdown = %v, want nil", err)
	}
	select {
	case <-finished:
	default:
		t.Fatal("Shutdown returned before the running job finished")
	}
	if pending := r.Pending(); len(pending) != 0 {
		t.Fatalf("pending = %v, want none", names(pending))
	}
}

func TestShutdownCancelsRunningJobsWhenContextEnds(t *testing.T) {
	r := NewRunner(2, 10, nil)
	r.Start()
	var startedWG sync.WaitGroup
	startedWG.Add(2)
	if err := r.Enqueue(Job{Name: "fails", Run: func(ctx context.Context) error {
		startedWG.Done()
		<-ctx.Done()
		return ctx.Err()
	}}); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(Job{Name: "finishes", Run: func(ctx context.Context) error {
		startedWG.Done()
		<-ctx.Done()
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	startedWG.Wait()
	if err := r.Enqueue(Job{Name: "queued", Run: func(context.Context) error {
		t.Error("queued job was started")
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
	}
	// The job that finished after its cancel is done; the one that returned an error is not.
	if got := names(r.Pending()); !slices.Equal(got, []string{"queued", "fails"}) {
		t.Fatalf("pending = %v, want [queued fails]", got)
	}
}

func TestPanickingJobIsRecovered(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	ran := make(chan struct{})
	if err := r.Enqueue(Job{Name: "boom", Run: func(context.Context) error { panic("boom") }}); err != nil {
		t.Fatal(err)
	}
	if err := r.Enqueue(Job{Name: "after", Run: func(context.Context) error {
		close(ran)
		return nil
	}}); err != nil {
		t.Fatal(err)
	}
	select {
	case <-ran:
	case <-time.After(5 * time.Second):
		t.Fatal("job after the panic did not run")
	}
	if err := r.Shutdown(context.Background()); err != nil {
		t.Fatal(err)
	}
	if pending := r.Pending(); len(pending) != 0 {
		t.Fatalf("pending = %v, want none", names(pending))
	}
}

func TestPanicAfterCancelIsNotPending(t *testing.T) {
	r := NewRunner(1, 10, nil)
	r.Start()
	started := make(chan struct{})
	if err := r.Enqueue(Job{Name: "panics", Run: func(ctx context.Context) error {
		close(started)
		<-ctx.Done()
		panic("after cancel")
	}}); err != nil {
		t.Fatal(err)
	}
	<-started
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Millisecond)
	defer cancel()
	if err := r.Shutdown(ctx); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("Shutdown = %v, want DeadlineExceeded", err)
